#!/usr/bin/env python3
"""Render and verify the security-ci bundle vendored across the fleet."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
MANIFEST_PATH = ROOT / "security-ci/consumers.json"
HEADER = (
    "# Generated by shizuha-tasks/scripts/security-ci-vendor.py; do not hand-edit.\n"
    "# Contract v{version}; source workflow sha256={source_sha}.\n"
)
BUNDLE_HASH_PLACEHOLDER = "0" * 64


def load_manifest() -> dict:
    return json.loads(MANIFEST_PATH.read_text())


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def source_bytes(manifest: dict) -> dict[str, bytes]:
    source = manifest["source"]
    return {
        "workflow": (ROOT / source["workflow"]).read_bytes(),
        "normalizer": (ROOT / source["normalizer"]).read_bytes(),
        "checker": (ROOT / source["checker"]).read_bytes(),
        "parity_template": (ROOT / source["parity_template"]).read_bytes(),
    }


def consumer(manifest: dict, repo: str) -> dict:
    for row in manifest["consumers"]:
        if row["repo"] == repo:
            return row
    raise KeyError(f"unknown security-ci consumer: {repo}")


def render_workflow(manifest: dict, row: dict, sources: dict[str, bytes]) -> bytes:
    text = sources["workflow"].decode()
    replacement = f"schedule:\n    - cron: '{row['schedule']}'"
    text, count = re.subn(
        r"schedule:\n\s+- cron:\s*['\"][^'\"]+['\"]",
        replacement,
        text,
        count=1,
    )
    if count != 1:
        raise ValueError("canonical workflow must contain exactly one schedule entry")
    if row["repo"] == manifest["source"]["repo"]:
        return text.encode()
    header = HEADER.format(
        version=manifest["contract_version"],
        source_sha=sha256(sources["workflow"]),
    )
    return (header + text).encode()


def render_bundle(manifest: dict, repo: str) -> dict[str, bytes]:
    row = consumer(manifest, repo)
    sources = source_bytes(manifest)
    workflow = render_workflow(manifest, row, sources)
    expected_workflow = sha256(workflow)
    parity = sources["parity_template"].decode().replace(
        "__EXPECTED_WORKFLOW_SHA256__", expected_workflow
    )
    parity = parity.replace("__EXPECTED_BUNDLE_SHA256__", BUNDLE_HASH_PLACEHOLDER)
    if "__EXPECTED_" in parity:
        raise ValueError("parity workflow hash placeholder was not rendered")
    bundle = {
        ".forgejo/workflows/security-ci.yml": workflow,
        ".forgejo/workflows/security-ci-parity.yml": parity.encode(),
        "scripts/check-security-ci-contract.py": sources["checker"],
        "scripts/security-ci-to-pulse.py": sources["normalizer"],
    }
    expected_bundle = bundle_sha256(bundle)
    bundle[".forgejo/workflows/security-ci-parity.yml"] = parity.replace(
        BUNDLE_HASH_PLACEHOLDER, expected_bundle, 1
    ).encode()
    return bundle


def bundle_sha256(bundle: dict[str, bytes]) -> str:
    digest = hashlib.sha256()
    for path in sorted(bundle):
        data = bundle[path]
        if path == ".forgejo/workflows/security-ci-parity.yml":
            data = re.sub(
                rb'expected_bundle = "[0-9a-f]{64}"',
                f'expected_bundle = "{BUNDLE_HASH_PLACEHOLDER}"'.encode(),
                data,
                count=1,
            )
        digest.update(path.encode())
        digest.update(b"\0")
        digest.update(str(len(data)).encode())
        digest.update(b"\0")
        digest.update(data)
        digest.update(b"\0")
    return digest.hexdigest()


def refresh_manifest(manifest: dict) -> None:
    sources = source_bytes(manifest)
    source = manifest["source"]
    for key, data in sources.items():
        source[f"{key}_sha256"] = sha256(data)
    for row in manifest["consumers"]:
        row["contract_version"] = manifest["contract_version"]
        row["expected_bundle_sha256"] = bundle_sha256(render_bundle(manifest, row["repo"]))
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")


def verify(manifest: dict, repo: str | None = None) -> list[str]:
    errors: list[str] = []
    sources = source_bytes(manifest)
    source = manifest["source"]
    for key, data in sources.items():
        expected = source.get(f"{key}_sha256")
        actual = sha256(data)
        if expected != actual:
            errors.append(f"source {key} sha256: expected {expected}, got {actual}")

    rows = manifest["consumers"]
    repos = [row["repo"] for row in rows]
    if len(repos) != 22 or len(set(repos)) != 22:
        errors.append("inventory must contain exactly 22 unique repositories")
    if source["repo"] not in repos:
        errors.append("canonical source repository is absent from inventory")

    selected = [consumer(manifest, repo)] if repo else rows
    for row in selected:
        if row["contract_version"] != manifest["contract_version"]:
            errors.append(f"{row['repo']}: contract version mismatch")
        actual = bundle_sha256(render_bundle(manifest, row["repo"]))
        if row["expected_bundle_sha256"] != actual:
            errors.append(
                f"{row['repo']}: bundle sha256 expected "
                f"{row['expected_bundle_sha256']}, got {actual}"
            )
    return errors


def main() -> int:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    verify_parser = sub.add_parser("verify")
    verify_parser.add_argument("--repo")
    render_parser = sub.add_parser("render")
    render_parser.add_argument("--repo", required=True)
    render_parser.add_argument("--output", type=Path, required=True)
    sub.add_parser("refresh-manifest")
    args = parser.parse_args()

    manifest = load_manifest()
    if args.command == "refresh-manifest":
        refresh_manifest(manifest)
        print(f"refreshed {MANIFEST_PATH}")
        return 0
    if args.command == "verify":
        errors = verify(manifest, args.repo)
        if errors:
            for error in errors:
                print(f"security-ci inventory error: {error}")
            return 1
        print(f"security-ci inventory: ok ({args.repo or '22 repos'})")
        return 0

    bundle = render_bundle(manifest, args.repo)
    for path, data in bundle.items():
        destination = args.output / path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(data)
    print(f"rendered {args.repo} security-ci bundle to {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
